import{u as o,j as s,f as d,C as a,c as h}from"./index-77EuQfhB.js";import{A as j}from"./Arrow-CqZSHgcn.js";import{L as l}from"./react-vendor-AIXwcq2c.js";const{fromYear:m,toYear:x}=a,p={ru:{title:"Как работает Altovisas",lede:t=>s.jsxs(s.Fragment,{children:["Altovisas сверяет ваши ответы для собеседования на F-1 с тем, что на самом деле происходило у окошка: с ",t," отзывами студентов о собственных собеседованиях с ",m," по ",x," год."]}),sections:[["Откуда берутся данные",["После собеседования многие студенты записывают, о чём их спрашивали, что они ответили и какое решение принял офицер, и публикуют это в открытом доступе. Мы собираем такие отзывы, убираем дубликаты и разбиваем каждый на вопросы, которые задал офицер. Так получается 37 типов вопросов и то, как часто каждый звучит в каждом консульстве. Каждый месяц добавляется примерно 200 новых рассказов."]],["Что происходит при проверке профиля",["Вы кратко рассказываете о себе (университет, программа, финансирование, консульство) и своими словами отвечаете на три вопроса, которые офицеры задают чаще всего. Мы находим самые похожие собеседования по консульству, стране и ступени обучения и всегда включаем случаи с отказом: если смотреть только на одобрения, не поймёшь, что губит кейс.","Модель ИИ читает ваши ответы вместе с этими собеседованиями и статистикой по вашему консульству и пишет отчёт: где офицер может засомневаться, о чём он может спросить дальше и как исправить каждый ответ. Ей запрещено придумывать цифры, она может приводить только те, что есть в данных."]],["Что цифры могут сказать, а что нет",["Отзывы пишут сами заявители. Люди сами решают, писать ли, а одобренные пишут охотнее, поэтому доля одобрений описывает тех, кто что-то написал, а не реальную долю одобрений в каком-либо консульстве. Закономерности в данных показывают связи, а не причины. Ничто здесь не предсказывает ваш результат: решает только консульский офицер."]]],limitsTitle:"Чего мы не делаем",limits:[["Не пишем за вас сценарий.","Заученные ответы часто становятся поводом для отказа. Советы касаются структуры, а слова остаются вашими."],["Не выдумываем за вас факты.","Ложное заявление у окошка может обернуться пожизненным запретом на въезд."],["Не обещаем визу.","Этого не может ни один сервис."],["Не даём юридических консультаций.","Это подготовка к собеседованию. Мы не юристы и не связаны ни с одним консульством или правительством."]],dataTitle:"Ваши данные",data:t=>s.jsxs(s.Fragment,{children:["То, что вы вводите, видно только в вашем аккаунте. Чтобы написать отчёт, ваш профиль и ответы передаются на обработку провайдеру ИИ. В ",t("Политике конфиденциальности")," описано, кто что обрабатывает, сколько это хранится и как удалить всё целиком."]}),tryTitle:"Попробуйте на своих ответах",tryBody:"Три вопроса, около четырёх минут. Нужен бесплатный аккаунт.",cta:"Начать проверку профиля"}};function g(){const{lang:t}=h(),e=o(p),n=i=>s.jsx(l,{to:"/privacy",children:i});return s.jsx("div",{className:"tf",children:s.jsxs("article",{className:"page-w doc",children:[s.jsx("h1",{children:e.title}),s.jsx("p",{className:"lede",children:e.lede(d(t,a.interviews))}),e.sections.map(([i,c])=>s.jsxs("section",{children:[s.jsx("h2",{children:i}),c.map(r=>s.jsx("p",{children:r},r))]},i)),s.jsxs("section",{children:[s.jsx("h2",{children:e.limitsTitle}),s.jsx("ul",{className:"doc-list",children:e.limits.map(([i,c])=>s.jsxs("li",{children:[s.jsx("strong",{children:i})," ",c]},i))})]}),s.jsxs("section",{children:[s.jsx("h2",{children:e.dataTitle}),s.jsx("p",{children:e.data(n)})]}),s.jsxs("section",{className:"doc-end",children:[s.jsx("h2",{children:e.tryTitle}),s.jsx("p",{children:e.tryBody}),s.jsxs(l,{to:"/check-profile",className:"btn",children:[e.cta," ",s.jsx(j,{})]})]})]})})}export{g as default};
